pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {W_WALLET} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(this));
    }

    function _run(uint256 _unlockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount == 0 || address(this).balance >= amount);
        bool reverted;
        try c.Put{value: amount}(_unlockTime) { reverted = false; } catch { reverted = true; }
        assertTrue(!(amount == 0) || reverted == false);
    }

    function testFuzz_run(uint256 _unlockTime, uint256 amount) public {
        _run(_unlockTime, amount);
    }

    receive() external payable { }
}
